"""Read-only independent manifest check and posthoc actual-input drift audit.
No stepping, fitting, selection changes or writes to sealed experiments.
"""
from pathlib import Path
import json,hashlib
import numpy as np
SRC=Path('/home/sensen/Desktop/engine修复验收/s5-neural-translator/20261106T003500Z');O=SRC.parent/'20261106T005511Z';O.mkdir(exist_ok=False)
def js(p):return json.loads(p.read_text())
def sha(p):
 h=hashlib.sha256()
 with Path(p).open('rb') as f:
  for block in iter(lambda:f.read(1048576),b''):h.update(block)
 return h.hexdigest()
def arrays(p):
 with np.load(p) as z:return {k:z[k] for k in z.files}
def dump(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
manifest=js(SRC/'MANIFEST_SHA256.json');mismatches=[p for p,h in manifest.items() if sha(p)!=h];assert not mismatches
s=js(SRC/'SUMMARY.json');candidate=next(v for v in s['candidates'] if v['name']=='lambda_50.0');r=next(v for v in candidate['results'] if v['release_time_s']==1.3);path=Path(candidate['model']);model=arrays(path);protect=arrays(SRC/'DATA/protection_old1.300.npz');actual=arrays(Path(r['folder'])/'NEURAL.npz');identity=js(SRC/'TRANSLATOR_IDENTITIES.json');limits=np.array(identity['limits']);mask=protect['eligible'];n=int(mask.sum());assert np.array_equal(np.flatnonzero(mask),np.arange(n))
def predict(x):return np.tanh(np.tanh(x@model['W0'].T)@model['W1'].T)@model['W2'].T
fit_actions=np.array([predict(x) for x in protect['x'][:n]]);live_actions=np.array([predict(x) for x in actual['features'][:n]]);assert np.array_equal(live_actions,actual['action'][:n]);assert np.array_equal(protect['x'][0],actual['features'][0])
def penalty(a,old):
 res=2*np.tanh(a);norm=old/limits;return float(.5*(np.mean(res**2)+np.mean((np.clip(norm+res,-1,1)-norm)**2)))
fit_penalty=penalty(fit_actions,protect['old'][:n]);live_penalty=penalty(live_actions,actual['old_torque'][:n]);history=js(path.parent/'FIT.json');best=next(x for x in history['history'] if x['epoch']==history['best_epoch']);assert abs(fit_penalty-best['protection_fit_loss'])<1e-6
feature_rms=np.sqrt(np.mean((actual['features'][:n]-protect['x'][:n])**2,axis=1));pred_rms=np.sqrt(np.mean((2*np.tanh(live_actions)-2*np.tanh(fit_actions))**2,axis=1));changed=np.flatnonzero(feature_rms>0)
oldsource=Path(str(protect['source'][0]));oldn=arrays(oldsource/'NEURAL.npz');spikediff=np.flatnonzero(np.any(actual['spikes204'][:n]!=oldn['spikes204'][:n],axis=(1,2)))
segments=[]
for start,end in [(0,10),(10,20),(20,40),(40,60),(60,n)]:
 if start>=n:continue
 end=min(end,n);segments.append(dict(window_ms=[start,end],same_time_feature_RMS_mean=float(feature_rms[start:end].mean()),live_zero_residual_penalty=penalty(live_actions[start:end],actual['old_torque'][start:end]),on_recorded_old_prefix_penalty=penalty(fit_actions[start:end],protect['old'][start:end])))
result=dict(importance='重要辅助',kind='posthoc observational diagnostic; no new simulation or training',source_experiment=str(SRC),manifest_entries_checked=len(manifest),manifest_mismatches=mismatches,model=str(path),model_sha256=sha(path),phase=1.3,prefix_actions=n,recorded_old_prefix_penalty=fit_penalty,recorded_fit_penalty=best['protection_fit_loss'],actual_closed_loop_same_time_penalty=live_penalty,first_neural_feature_difference_ms=None if not len(changed) else int(changed[0]),first_spike_difference_window_ms=None if not len(spikediff) else int(spikediff[0]),first_nonfoot_ms=1000*r['parts']['first_nonfoot_s'],segments=segments,
 interpretation='Small protection loss on old trajectory did not remain small on inputs generated by the new closed loop. Same-time paired comparison is observational; large corrections after divergence are not proven wrong or uniquely causal. Does not establish missing information, a required action, or walking intention. No future data enters inference.',source_hashes={str(p):sha(p) for p in [SRC/'SUMMARY.json',SRC/'DATA/protection_old1.300.npz',Path(r['folder'])/'NEURAL.npz',oldsource/'NEURAL.npz',path,path.parent/'FIT.json',SRC/'MANIFEST_SHA256.json']})
dump(O/'ACTUAL_INPUT_AUDIT.json',result)
np.savez_compressed(O/'PAIRED_PREFIX.npz',feature_rms=feature_rms,residual_difference_rms=pred_rms,fit_actions=fit_actions,actual_actions=live_actions)
text=f'''# 回归保护失败：独立结果核验与实际输入检查

重要辅助；本补充不启动新物理模拟、不训练、不改变已冻结选模。

重新校验`{SRC}/MANIFEST_SHA256.json`内{len(manifest)}个文件，0不匹配。

罚权50在旧轨迹99点上的保护损失为{fit_penalty:.9f}，和已保存训练值吻合；同一网络在自己实际闭环相同99ms时间段的零残差诊断量为{live_penalty:.9f}。这说明保存样本上的保护拟合并没有覆盖实际闭环输入，不代表这些新状态下零残差必然正确。

首个神经特征差异发生在撤辅{result['first_neural_feature_difference_ms']}ms；首个尖峰差异出现在{result['first_spike_difference_window_ms']}ms起的动作窗口。实际首次非足触地约{result['first_nonfoot_ms']:.4f}ms。差异时间仅为保存数据上的观察，不是完整因果机制或延迟测量。

逐窗数值、源文件哈希见`{O}/ACTUAL_INPUT_AUDIT.json`；配对数组见`{O}/PAIRED_PREFIX.npz`。所有文件重要辅助，用于解释离线拟合和真实闭环的差别；没有待清理临时输出。
'''
(O/'REPORT.zh-CN.md').write_text(text)
dump(O/'MANIFEST_SHA256.json',{str(p):sha(p) for p in [*sorted(O.iterdir()),Path(__file__)] if p.is_file()})
print(json.dumps(result,ensure_ascii=False),flush=True)
